INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE.M_INDICES_MULTIPLIED_FOR_PRODUCT', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE', 'Multiplies the indices when multiplying powers.', '{"question":"2 to the 3 x 2 to the 4","wrong_answer":"2 to the 12","correct_answer":"2 to the 7"}'::jsonb, 'Uses the power-of-a-power law.', 'The answer 2 to the 12 as a wrong option, with a reason that names the idea.', 'Write out the factors: three 2s then four 2s make seven 2s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE.M_BASES_MULTIPLIED', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE', 'Multiplies the bases as well as adding the indices.', '{"question":"3 squared x 3 to the 4","wrong_answer":"9 to the 6","correct_answer":"3 to the 6"}'::jsonb, 'Thinks every number in a product is multiplied.', 'The answer 9 to the 6 as a wrong option, with a reason that names the idea.', 'The factors are all 3s; the base stays 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE.M_BASES_ADDED', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE', 'Adds the bases.', '{"question":"5 squared x 5 cubed","wrong_answer":"10 to the 5","correct_answer":"5 to the 5"}'::jsonb, 'Adds everything it sees.', 'The answer 10 to the 5 as a wrong option, with a reason that names the idea.', 'Bases are never added in the laws: 5 to the 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE.M_INDEX_AS_REPEATED_ADDITION', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE', 'Multiplies the base by the sum of the indices.', '{"question":"2 to the 3 x 2 to the 2","wrong_answer":"10","correct_answer":"32"}'::jsonb, 'Reads the index as a multiplier.', 'The answer 10 as a wrong option, with a reason that names the idea.', '2 to the 5 is five 2s multiplied, not 2 x 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE.M_DIVIDE_INDICES_ADDED', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE', 'Adds the indices when dividing powers.', '{"question":"2 to the 10 divided by 2 to the 4","wrong_answer":"2 to the 14","correct_answer":"2 to the 6"}'::jsonb, 'Uses the multiplication law for every operation.', 'The answer 2 to the 14 as a wrong option, with a reason that names the idea.', 'Dividing cancels factors: take 4 from 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE.M_DIVIDE_INDICES_MULTIPLIED', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE', 'Multiplies the indices when dividing powers.', '{"question":"2 to the 10 divided by 2 to the 4","wrong_answer":"2 to the 40","correct_answer":"2 to the 6"}'::jsonb, 'Picks an operation without a reason.', 'The answer 2 to the 40 as a wrong option, with a reason that names the idea.', 'Write it as a fraction and cancel the factors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE.M_INDEX_GIVEN_AS_VALUE', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LAWS_MULTIPLY_DIVIDE', 'Gives the index of the answer as the answer.', '{"question":"How many pieces of 2 cubed cm from 2 to the 7 cm?","wrong_answer":"4","correct_answer":"16"}'::jsonb, 'Stops after working out the index.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'The answer is 2 to the power 4, which is 16.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.ZERO_INDEX_POWER_OF_POWER.M_ZERO_INDEX_IS_ZERO', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.ZERO_INDEX_POWER_OF_POWER', 'Says any number to the power 0 is 0.', '{"question":"7 to the power 0","wrong_answer":"0","correct_answer":"1"}'::jsonb, 'Thinks the index multiplies the base.', 'The answer 0 as a wrong option, with a reason that names the idea.', '7 cubed divided by 7 cubed is 1, and by the law it is 7 to the 0.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.ZERO_INDEX_POWER_OF_POWER.M_ZERO_INDEX_IS_BASE', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.ZERO_INDEX_POWER_OF_POWER', 'Says a number to the power 0 is the number itself.', '{"question":"9 to the power 0","wrong_answer":"9","correct_answer":"1"}'::jsonb, 'Mixes up the index 0 and the index 1.', 'The answer 9 as a wrong option, with a reason that names the idea.', 'An index of 1 leaves the number; 0 gives 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.ZERO_INDEX_POWER_OF_POWER.M_ZERO_INDEX_UNDEFINED', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.ZERO_INDEX_POWER_OF_POWER', 'Says a number to the power 0 has no value.', '{"question":"12 to the power 0","wrong_answer":"It has no value","correct_answer":"1"}'::jsonb, 'Cannot picture multiplying a number zero times.', 'The answer It has no value as a wrong option, with a reason that names the idea.', 'The division law gives it a value: 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.ZERO_INDEX_POWER_OF_POWER.M_POWER_OF_POWER_ADDED', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.ZERO_INDEX_POWER_OF_POWER', 'Adds the indices for a power of a power.', '{"question":"(2 cubed) squared","wrong_answer":"2 to the 5","correct_answer":"2 to the 6"}'::jsonb, 'Uses the multiplication law.', 'The answer 2 to the 5 as a wrong option, with a reason that names the idea.', '(2 cubed) squared is 2 cubed x 2 cubed: 3 + 3 = 6, which is 3 x 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
