INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_LAWS.M_LOG_AS_TENTH', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_LAWS', 'Writes the log of a power of 10 as the number divided by 10.', '{"question":"log 1,000","wrong_answer":"100","correct_answer":"3"}'::jsonb, 'Thinks a logarithm shrinks the number by 10.', 'The answer 100 as a wrong option, with a reason that names the idea.', 'The log is the index: 1,000 = 10 cubed, so log 1,000 = 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_SCALE_CONTEXT.M_LOG_DIFFERENCE_AS_RATIO', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_SCALE_CONTEXT', 'Gives the difference in magnitude as how many times larger.', '{"question":"Magnitude 5 and magnitude 3. How many times larger?","wrong_answer":"2","correct_answer":"100"}'::jsonb, 'Treats the scale like a ruler.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Each step multiplies by 10: two steps is 10 x 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_SCALE_CONTEXT.M_TEN_TIMES_DIFFERENCE', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_SCALE_CONTEXT', 'Multiplies the difference by 10.', '{"question":"Magnitude 6 and magnitude 3. How many times larger?","wrong_answer":"30","correct_answer":"1,000"}'::jsonb, 'Knows 10 is involved but adds the steps instead of multiplying.', 'The answer 30 as a wrong option, with a reason that names the idea.', 'Three steps of x 10 is 10 cubed = 1,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_SCALE_CONTEXT.M_LOGS_DIVIDED', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_SCALE_CONTEXT', 'Divides one magnitude by the other.', '{"question":"Magnitude 6 and magnitude 3. How many times larger?","wrong_answer":"2","correct_answer":"1,000"}'::jsonb, 'Compares the readings as if they were the sizes.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Change each reading back to a power of 10 first: 10 to the 6 over 10 cubed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_SCALE_CONTEXT.M_SCALE_LINEAR', 'MATH.G9.NUMBER.INDICES_AND_LOGARITHMS.LOG_SCALE_CONTEXT', 'Thinks equal steps on the scale are equal amounts added.', '{"question":"From magnitude 4 to 5 and from 5 to 6: is the increase the same?","wrong_answer":"Yes, both add 1","correct_answer":"No: the second is 10 times bigger"}'::jsonb, 'Pictures the scale as a ruler.', 'The answer Yes, both add 1 as a wrong option, with a reason that names the idea.', 'Each step multiplies the size by 10, so later steps add far more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS.M_SHARED_EQUALLY', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS', 'Shares the amount equally, ignoring the ratio.', '{"question":"Share 36,000 in the ratio 2:3:4. The largest share?","wrong_answer":"12,000","correct_answer":"16,000"}'::jsonb, 'Hears "share" and divides by the number of people.', 'The answer 12,000 as a wrong option, with a reason that names the idea.', 'The ratio says how many parts each gets: 2 + 3 + 4 = 9 parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS.M_ONE_PART_GIVEN', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS', 'Gives the value of one part as a share.', '{"question":"Share 36,000 in the ratio 2:3:4. The largest share?","wrong_answer":"4,000","correct_answer":"16,000"}'::jsonb, 'Stops after dividing by the total parts.', 'The answer 4,000 as a wrong option, with a reason that names the idea.', 'That is one part; this club gets 4 parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS.M_DIVIDE_BY_OWN_PART', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS', 'Divides the amount by the person''s own number of parts.', '{"question":"Share 36,000 in the ratio 2:3:4. The largest share?","wrong_answer":"9,000","correct_answer":"16,000"}'::jsonb, 'Uses the share number as the divisor.', 'The answer 9,000 as a wrong option, with a reason that names the idea.', 'First divide by all the parts (9), then multiply by 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS.M_PARTS_MULTIPLIED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS', 'Multiplies the numbers in the ratio to get the total parts.', '{"question":"Share 2,000 in the ratio 2:3. Total parts?","wrong_answer":"6","correct_answer":"5"}'::jsonb, 'Combines the ratio numbers by multiplying.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'Parts are counted: 2 parts and 3 parts make 5 parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS.M_PARTS_AS_HUNDREDS', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.PROPORTIONAL_PARTS', 'Treats the ratio numbers as amounts of 100 shillings.', '{"question":"Profit 45,000 shared 2:3:4. The 3-part share?","wrong_answer":"300","correct_answer":"15,000"}'::jsonb, 'Attaches a unit to the ratio numbers.', 'The answer 300 as a wrong option, with a reason that names the idea.', 'A part is worth the amount divided by the total parts, whatever it comes to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN.M_SHARED_TERM_NOT_MATCHED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN', 'Joins two ratios without making the shared term equal.', '{"question":"Maize:beans = 2:3, beans:peas = 4:5. Maize:beans:peas?","wrong_answer":"2:3:5","correct_answer":"8:12:15"}'::jsonb, 'Sees the shared word and writes the numbers side by side.', 'The answer 2:3:5 as a wrong option, with a reason that names the idea.', 'Make the beans the same in both ratios: 12 in each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN.M_WRONG_PAIR_USED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN', 'Uses the second ratio as if it compared the first and third items.', '{"question":"Cows:goats = 2:3, goats:hens = 2:5, 20 cows. Hens?","wrong_answer":"50","correct_answer":"75"}'::jsonb, 'Reads goats:hens as cows:hens.', 'The answer 50 as a wrong option, with a reason that names the idea.', 'Go through the goats: cows to goats, then goats to hens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN.M_MIDDLE_GIVEN', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN', 'Gives the number for the shared item instead of the one asked.', '{"question":"Cows:goats = 2:3, goats:hens = 3:4, 20 cows. Hens?","wrong_answer":"30","correct_answer":"40"}'::jsonb, 'Stops after one step.', 'The answer 30 as a wrong option, with a reason that names the idea.', 'That is the goats; one more step to the hens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN.M_RATIOS_ADDED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN', 'Adds the two ratios term by term.', '{"question":"Maize:beans = 2:3, beans:peas = 4:5. Combine.","wrong_answer":"6:8","correct_answer":"8:12:15"}'::jsonb, 'Thinks ratios combine like fractions or sums.', 'The answer 6:8 as a wrong option, with a reason that names the idea.', 'Ratios are not added; match the shared term.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN.M_RATIO_TERMS_SUMMED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATIO_CHAIN', 'Adds the numbers of a ratio to find one part when combining.', '{"question":"Maize:beans = 2:3 and beans:peas = 4:5. Why not 2:3:5?","wrong_answer":"Because 2 + 3 = 5 is one part","correct_answer":"Because the beans are not matched"}'::jsonb, 'Mixes up sharing with combining ratios.', 'The answer Because 2 + 3 = 5 is one part as a wrong option, with a reason that names the idea.', 'Combining ratios needs the shared term equal, not a sum.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION.M_ONE_CHANGE_ONLY_TIME', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION', 'Adjusts for the change in number and ignores the change in time.', '{"question":"4 machines grind 1,200 kg in 6 h. 6 machines in 5 h?","wrong_answer":"1,800","correct_answer":"1,500"}'::jsonb, 'Handles one change and stops.', 'The answer 1,800 as a wrong option, with a reason that names the idea.', 'Both changed: also multiply by 5/6 for the hours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION.M_ONE_CHANGE_ONLY_NUMBER', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION', 'Adjusts for the change in time and ignores the change in number of machines or workers.', '{"question":"4 machines grind 1,200 kg in 6 h. 6 machines in 5 h?","wrong_answer":"1,000","correct_answer":"1,500"}'::jsonb, 'Handles one change and stops.', 'The answer 1,000 as a wrong option, with a reason that names the idea.', 'More machines grind more: also multiply by 6/4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION.M_UNIT_RATE_NOT_DIVIDED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION', 'Finds the rate for one machine for one hour by dividing by only one of the two.', '{"question":"4 machines grind 1,200 kg in 6 h. One machine in one hour?","wrong_answer":"300","correct_answer":"50"}'::jsonb, 'Divides by machines but forgets the hours.', 'The answer 300 as a wrong option, with a reason that names the idea.', 'Divide by both: 1,200 / 4 / 6 = 50.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION.M_UNIT_MULTIPLIED_NOT_DIVIDED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION', 'Multiplies when reducing to one unit instead of dividing.', '{"question":"24 worker-days for 3 shambas. Worker-days for 1 shamba?","wrong_answer":"72","correct_answer":"8"}'::jsonb, 'Uses multiplication at every step.', 'The answer 72 as a wrong option, with a reason that names the idea.', 'One shamba needs less work: divide by 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION.M_WORKERS_MULTIPLIED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.COMPOUND_PROPORTION', 'Multiplies the work by the workers instead of sharing it among them.', '{"question":"40 worker-days shared by 5 workers. Days?","wrong_answer":"200","correct_answer":"8"}'::jsonb, 'Forgets that workers share the work.', 'The answer 200 as a wrong option, with a reason that names the idea.', 'Workers share the worker-days: divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION.M_INVERSE_AS_DIRECT', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION', 'Makes the answer bigger when more workers do the same job.', '{"question":"6 workers take 10 days. 12 workers?","wrong_answer":"20","correct_answer":"5"}'::jsonb, 'Assumes every proportion is direct.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'More workers finish sooner: the days go down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION.M_TABLE_ROW_COPIED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION', 'Copies the days for a different number of workers from the table.', '{"question":"Table: 2 workers 30 days, 3 workers 20 days. 5 workers?","wrong_answer":"20","correct_answer":"12"}'::jsonb, 'Picks the nearest row.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'Find the worker-days (60) and divide by 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION.M_CONSTANT_AS_ANSWER', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION', 'Gives the constant product (worker-days) as the answer.', '{"question":"2 workers take 30 days. 5 workers?","wrong_answer":"60","correct_answer":"12"}'::jsonb, 'Stops after finding the constant.', 'The answer 60 as a wrong option, with a reason that names the idea.', 'Divide the worker-days by the workers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION.M_INVERSE_SUM_CONSTANT', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION', 'Thinks the sum of the two quantities stays the same in inverse proportion.', '{"question":"d varies inversely as p; 4 people, 15 days. 6 people?","wrong_answer":"13","correct_answer":"10"}'::jsonb, 'Expects one to go down as much as the other goes up.', 'The answer 13 as a wrong option, with a reason that names the idea.', 'The product stays the same: 4 x 15 = 60, so 60 / 6 = 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION.M_CONSTANT_MULTIPLIED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION', 'Multiplies the constant by the given value instead of dividing.', '{"question":"p x d = 60. Find p when d = 5.","wrong_answer":"300","correct_answer":"12"}'::jsonb, 'Forgets that p = 60 / d.', 'The answer 300 as a wrong option, with a reason that names the idea.', 'p x 5 = 60, so p = 60 / 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION.M_TEST_WRONG_WAY', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.INVERSE_PROPORTION', 'Checks for inverse proportion by dividing (or for direct by multiplying).', '{"question":"x: 1, 2, 3; y: 12, 6, 4. Direct or inverse?","wrong_answer":"Neither, y / x changes","correct_answer":"Inverse, x x y = 12"}'::jsonb, 'Uses one test for both kinds.', 'The answer Neither, y / x changes as a wrong option, with a reason that names the idea.', 'Direct: y / x stays the same. Inverse: x x y stays the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATE_OF_WORK_TOGETHER.M_TIMES_AVERAGED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATE_OF_WORK_TOGETHER', 'Takes the average of the two times as the time together.', '{"question":"Taps fill a tank in 4 h and 6 h. Together?","wrong_answer":"5 h","correct_answer":"2.4 h"}'::jsonb, 'Thinks together is "in between".', 'The answer 5 h as a wrong option, with a reason that names the idea.', 'Together is quicker than the faster tap alone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATE_OF_WORK_TOGETHER.M_TIMES_ADDED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATE_OF_WORK_TOGETHER', 'Adds the times for working together.', '{"question":"Taps fill a tank in 4 h and 6 h. Together?","wrong_answer":"10 h","correct_answer":"2.4 h"}'::jsonb, 'Adds the numbers in the story.', 'The answer 10 h as a wrong option, with a reason that names the idea.', 'Add the parts done in an hour, not the times.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATE_OF_WORK_TOGETHER.M_TIMES_SUBTRACTED', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATE_OF_WORK_TOGETHER', 'Subtracts the times.', '{"question":"Taps fill a tank in 4 h and 6 h. Together?","wrong_answer":"2 h","correct_answer":"2.4 h"}'::jsonb, 'Looks for a smaller number.', 'The answer 2 h as a wrong option, with a reason that names the idea.', 'Times are not subtracted: 1/4 + 1/6 = 5/12 an hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATE_OF_WORK_TOGETHER.M_DAYS_AS_RATE', 'MATH.G9.NUMBER.COMPOUND_PROPORTIONS_AND.RATE_OF_WORK_TOGETHER', 'Uses the number of days as the work done each day.', '{"question":"Field = 60 units, done alone in 12 days. Units a day?","wrong_answer":"12","correct_answer":"5"}'::jsonb, 'Mixes up time and rate.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Rate = work / time: 60 / 12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
