INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS.M_UNKNOWN_ADDED_NOT_SUBTRACTED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS', 'Adds the known element to the answer instead of taking it away.', '{"question":"x + 4 = 9 from a matrix sum. x?","wrong_answer":"13","correct_answer":"5"}'::jsonb, 'Adds the numbers in the same position.', 'The answer 13 as a wrong option, with a reason that names the idea.', 'Undo the addition: x = 9 - 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS.M_ANSWER_ELEMENTS_GIVEN', 'MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS', 'Gives the elements of the answer matrix as the unknowns.', '{"question":"[x 3] + [4 1] = [9 4]. x?","wrong_answer":"9","correct_answer":"5"}'::jsonb, 'Reads x from the result.', 'The answer 9 as a wrong option, with a reason that names the idea.', 'x is in the first matrix, before the addition.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS.M_SUM_AS_PRODUCT', 'MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS', 'Multiplies the unknowns when their sum is asked.', '{"question":"x = 5, y = 4. x + y?","wrong_answer":"20","correct_answer":"9"}'::jsonb, 'Misreads the question.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'x + y means add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS.M_WRONG_POSITION_MATCHED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS', 'Matches an unknown with an element in another position.', '{"question":"[x 3; 2 y] + [4 1; 5 2] = [9 4; 7 6]. y?","wrong_answer":"5 (7 - 2)","correct_answer":"4 (6 - 2)"}'::jsonb, 'Pairs by order of reading, not by position.', 'The answer 5 (7 - 2) as a wrong option, with a reason that names the idea.', 'y is in row 2, column 2: use row 2, column 2 on each side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE.M_PERCENT_NOT_DIVIDED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE', 'Multiplies the percentage by the distance and forgets to divide by 100.', '{"question":"A 6% road, 450 m across. Rise?","wrong_answer":"2,700 m","correct_answer":"27 m"}'::jsonb, 'Treats 6% as 6.', 'The answer 2,700 m as a wrong option, with a reason that names the idea.', '6% means 6 for every 100: 450 x 6 / 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE.M_DIVIDE_BY_GRADIENT', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE', 'Divides the distance by the gradient instead of multiplying.', '{"question":"A 6% road, 450 m across. Rise?","wrong_answer":"75 m","correct_answer":"27 m"}'::jsonb, 'Picks an operation without a reason.', 'The answer 75 m as a wrong option, with a reason that names the idea.', 'Rise = gradient x run.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE.M_GRADIENT_ADDED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE', 'Adds the gradient to the distance.', '{"question":"A 6% road, 450 m across. Rise?","wrong_answer":"456 m","correct_answer":"27 m"}'::jsonb, 'Treats the gradient as a distance.', 'The answer 456 m as a wrong option, with a reason that names the idea.', 'The gradient is a rate, not a length.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE.M_RISE_ONLY_COMPARED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE', 'Compares slopes by the rise alone, ignoring the run.', '{"question":"Roof A rises 3 m over 4 m; roof B rises 4 m over 8 m. Steeper?","wrong_answer":"B","correct_answer":"A"}'::jsonb, 'Thinks higher means steeper.', 'The answer B as a wrong option, with a reason that names the idea.', 'Steepness is rise / run: 0.75 against 0.5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE.M_RUN_OVER_RISE', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE', 'Divides the run by the rise.', '{"question":"Rise 3 m, run 4 m. Gradient?","wrong_answer":"1.33","correct_answer":"0.75"}'::jsonb, 'Divides the bigger by the smaller.', 'The answer 1.33 as a wrong option, with a reason that names the idea.', 'Up over across: 3 / 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS.M_GRADIENT_SIGN_LOST', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS', 'Gives a positive gradient for a line going down.', '{"question":"(0, 50) and (10, 20): gradient?","wrong_answer":"3","correct_answer":"-3"}'::jsonb, 'Takes the size of the change only.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'y goes down as x goes up: negative.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS.M_GRADIENT_UPSIDE_DOWN', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS', 'Divides the change in x by the change in y.', '{"question":"(1, 2) and (3, 8): gradient?","wrong_answer":"1/3","correct_answer":"3"}'::jsonb, 'Puts x on top because x comes first.', 'The answer 1/3 as a wrong option, with a reason that names the idea.', 'Change in y over change in x: 6 / 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS.M_CHANGE_IN_Y_ONLY', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS', 'Gives the change in y as the gradient.', '{"question":"(0, 50) and (10, 20): gradient?","wrong_answer":"-30","correct_answer":"-3"}'::jsonb, 'Stops before dividing.', 'The answer -30 as a wrong option, with a reason that names the idea.', 'Divide by the change in x as well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS.M_SUBTRACTION_ORDER_MIXED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS', 'Subtracts y one way and x the other way.', '{"question":"(1, 7) and (4, 1): gradient?","wrong_answer":"2","correct_answer":"-2"}'::jsonb, 'Takes the larger minus the smaller each time.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Use the same order: (1 - 7) / (4 - 1).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS.M_CHANGES_MULTIPLIED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS', 'Multiplies the changes instead of dividing.', '{"question":"Change in y -6, change in x 3. Gradient?","wrong_answer":"-18","correct_answer":"-2"}'::jsonb, 'Picks the wrong operation.', 'The answer -18 as a wrong option, with a reason that names the idea.', 'Gradient = change in y divided by change in x.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS.M_NEGATIVE_COORDINATE_SUBTRACTED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_TWO_POINTS', 'Subtracts a negative coordinate as if it were positive.', '{"question":"(-2, 1) and (3, 11): change in x?","wrong_answer":"1","correct_answer":"5"}'::jsonb, 'Drops the sign of -2.', 'The answer 1 as a wrong option, with a reason that names the idea.', '3 - (-2) = 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_TWO_POINTS.M_C_AS_POINT_Y', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_TWO_POINTS', 'Takes the y-value of a point as c.', '{"question":"Line through (2, 7) and (5, 13). c?","wrong_answer":"7","correct_answer":"3"}'::jsonb, 'Thinks any y-value on the line is c.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'c is y where x = 0: 7 = 2 x 2 + c gives c = 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_TWO_POINTS.M_C_BY_ADDING', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_TWO_POINTS', 'Adds m times x to y instead of taking it away to find c.', '{"question":"m = 2, point (2, 7). c?","wrong_answer":"11","correct_answer":"3"}'::jsonb, 'Moves the term without changing its sign.', 'The answer 11 as a wrong option, with a reason that names the idea.', 'c = y - mx = 7 - 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
