INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_TWO_POINTS.M_M_C_SWAPPED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_TWO_POINTS', 'Writes the equation with m and c swapped.', '{"question":"m = 2, c = 3. Equation?","wrong_answer":"y = 3x + 2","correct_answer":"y = 2x + 3"}'::jsonb, 'Does not know which number goes with x.', 'The answer y = 3x + 2 as a wrong option, with a reason that names the idea.', 'm multiplies x; c stands alone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_POINT_GRADIENT.M_MX_SIGN_WRONG', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_POINT_GRADIENT', 'Gets the sign of m times x wrong when m is negative.', '{"question":"m = -3, point (2, 1). c?","wrong_answer":"-5","correct_answer":"7"}'::jsonb, 'Writes -3 x 2 as 6.', 'The answer -5 as a wrong option, with a reason that names the idea.', '-3 x 2 = -6, so 1 = -6 + c and c = 7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
