INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_POINT_GRADIENT.M_POINT_X_AS_C', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_POINT_GRADIENT', 'Uses the x-value of the point as c.', '{"question":"m = 3, point (2, 7). c?","wrong_answer":"2","correct_answer":"1"}'::jsonb, 'Thinks c comes from the point directly.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Substitute: 7 = 3 x 2 + c, c = 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_POINT_GRADIENT.M_MX_AS_SUM_D', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.EQUATION_POINT_GRADIENT', 'Adds m and the x-value instead of multiplying.', '{"question":"m = 4, point (3, 20). c?","wrong_answer":"13","correct_answer":"8"}'::jsonb, 'Reads m times x as m + x.', 'The answer 13 as a wrong option, with a reason that names the idea.', 'm times x = 4 x 3 = 12, so c = 20 - 12 = 8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C.M_TERM_MOVED_SIGN_KEPT', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C', 'Moves the x term to the other side without changing its sign.', '{"question":"3x + 2y = 8: 2y = ?","wrong_answer":"3x + 8","correct_answer":"-3x + 8"}'::jsonb, 'Moves terms like objects.', 'The answer 3x + 8 as a wrong option, with a reason that names the idea.', 'Take 3x from both sides: -3x.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C.M_NOT_ALL_DIVIDED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C', 'Divides only one term by the number in front of y.', '{"question":"2y = -6x + 8: y = ?","wrong_answer":"-6x + 4","correct_answer":"-3x + 4"}'::jsonb, 'Divides the term next to the equals sign only.', 'The answer -6x + 4 as a wrong option, with a reason that names the idea.', 'Divide every term by 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C.M_CONSTANT_SIGN_CHANGED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C', 'Changes the sign of the constant as well as the term that moved.', '{"question":"3x + 2y = 8: 2y = ?","wrong_answer":"-3x - 8","correct_answer":"-3x + 8"}'::jsonb, 'Changes every sign when anything moves.', 'The answer -3x - 8 as a wrong option, with a reason that names the idea.', 'Only the term that crosses the equals sign changes sign.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C.M_GRADIENT_SIGN_WRONG_E', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C', 'Gives m with the wrong sign after rearranging.', '{"question":"3x + 2y = 8: m?","wrong_answer":"3/2","correct_answer":"-3/2"}'::jsonb, 'Reads the 3 from the first equation.', 'The answer 3/2 as a wrong option, with a reason that names the idea.', 'Read m only after y is the subject: y = -3/2 x + 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C.M_M_C_READ_SWAPPED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.REARRANGE_Y_MX_C', 'Reads c as m and m as c from y = mx + c.', '{"question":"y = 4x - 3: m and c?","wrong_answer":"m = -3, c = 4","correct_answer":"m = 4, c = -3"}'::jsonb, 'Reads the numbers in order of size or place.', 'The answer m = -3, c = 4 as a wrong option, with a reason that names the idea.', 'm is with x; c stands alone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERPRET_M_AND_C.M_GRADIENT_AS_FIXED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERPRET_M_AND_C', 'Calls the gradient the fixed charge.', '{"question":"Fare y = 40x + 100. Fixed charge?","wrong_answer":"40","correct_answer":"100"}'::jsonb, 'Takes the first number.', 'The answer 40 as a wrong option, with a reason that names the idea.', 'c is the cost before any distance: x = 0.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
