INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERPRET_M_AND_C.M_ONE_KM_TAKEN_OFF', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERPRET_M_AND_C', 'Takes away the cost of only 1 km from a fare.', '{"question":"3 km costs 220 at 40 a km. Fixed charge?","wrong_answer":"180","correct_answer":"100"}'::jsonb, 'Takes off one rate.', 'The answer 180 as a wrong option, with a reason that names the idea.', 'Take off the cost of all 3 km.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERPRET_M_AND_C.M_C_AS_STEEPNESS', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERPRET_M_AND_C', 'Thinks the line with the bigger c is steeper.', '{"question":"y = 2x + 9 or y = 5x + 1: steeper?","wrong_answer":"y = 2x + 9","correct_answer":"y = 5x + 1"}'::jsonb, 'Looks at the largest number.', 'The answer y = 2x + 9 as a wrong option, with a reason that names the idea.', 'Steepness is m; c only moves the line up or down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
